// 1. รับรายการไฟล์ทั้งหมดจาก Node ก่อนหน้า
const allFiles = $input.all();

// 2. สุ่มเลือกมา 1 ไฟล์
const randomIndex = Math.floor(Math.random() * allFiles.length);
const randomFile = allFiles[randomIndex].json;

// 3. ส่งข้อมูลไฟล์ที่สุ่มได้ออกไป (ID, Name, WebContentLink)
return {
  fileId: randomFile.id,
  fileName: randomFile.name,
  // สร้าง Link รูปภาพสำหรับ Facebook (ต้องเป็น webContentLink หรือ webViewLink)
  imageUrl: randomFile.webContentLink || randomFile.webViewLink
};
